31: typealias ResourceSearchParams = Map<ResourceType, ParamMap>
32: 
33: /**
34:  * [DownloadWorkManager] implementation based on the provided [ResourceSearchParams] to generate
35:  * [Resource] search queries and parse [Bundle.BundleType.Searchset] type [Bundle]. This
36:  * implementation takes a DFS approach and downloads all available resources for a particular
37:  * [ResourceType] before moving on to the next [ResourceType].
38:  */
39: class ResourceParamsBasedDownloadWorkManager(
40:   syncParams: ResourceSearchParams,
41:   val context: TimestampContext,
42: ) : DownloadWorkManager {
43:   private val resourcesToDownloadWithSearchParams = ArrayDeque(syncParams.entries)
44:   private val urlOfTheNextPagesToDownloadForAResource = ArrayDeque<String>()
45: 
46:   override suspend fun getNextRequest(): DownloadRequest? {
47:     if (urlOfTheNextPagesToDownloadForAResource.isNotEmpty()) {
48:       return urlOfTheNextPagesToDownloadForAResource.removeFirstOrNull()?.let {
49:         DownloadRequest.of(it)
50:       }
51:     }
52: 
53:     return resourcesToDownloadWithSearchParams.removeFirstOrNull()?.let { (resourceType, params) ->
54:       val newParams =
55:         params.toMutableMap().apply { putAll(getLastUpdatedParam(resourceType, params, context)) }
56: 
57:       DownloadRequest.of("${resourceType.name}?${newParams.concatParams()}")
58:     }
59:   }
60: 
61:   /**
62:    * Returns the map of resourceType and URL for summary of total count for each download request
63:    */
64:   override suspend fun getSummaryRequestUrls(): Map<ResourceType, String> {
65:     return resourcesToDownloadWithSearchParams.associate { (resourceType, params) ->
66:       val newParams =
67:         params.toMutableMap().apply {
68:           putAll(getLastUpdatedParam(resourceType, params, context))
69:           putAll(getSummaryParam(params))
70:         }
71: 
72:       resourceType to "${resourceType.name}?${newParams.concatParams()}"
73:     }
74:   }
75: 
76:   private suspend fun getLastUpdatedParam(
77:     resourceType: ResourceType,
78:     params: ParamMap,
79:     context: TimestampContext,
80:   ): MutableMap<String, String> {
81:     val newParams = mutableMapOf<String, String>()
82:     if (!params.containsKey(SyncDataParams.SORT_KEY)) {
83:       newParams[SyncDataParams.SORT_KEY] = SyncDataParams.LAST_UPDATED_KEY
84:     }
85:     if (!params.containsKey(SyncDataParams.LAST_UPDATED_KEY)) {
86:       val lastUpdate = context.getLasUpdateTimestamp(resourceType)
87:       if (!lastUpdate.isNullOrEmpty()) {
88:         newParams[SyncDataParams.LAST_UPDATED_KEY] = "$GREATER_THAN_PREFIX$lastUpdate"
89:       }
90:     }
91:     return newParams
92:   }
93: 
94:   private fun getSummaryParam(params: ParamMap): MutableMap<String, String> {
95:     val newParams = mutableMapOf<String, String>()
96:     if (!params.containsKey(SyncDataParams.SUMMARY_KEY)) {
97:       newParams[SyncDataParams.SUMMARY_KEY] = SyncDataParams.SUMMARY_COUNT_VALUE
98:     }
99:     return newParams
100:   }
101: 
102:   override suspend fun processResponse(response: Resource): Collection<Resource> {
103:     if (response is OperationOutcome) {
104:       throw IllegalStateException(response.issue.firstOrNull()?.diagnostics?.value)
105:     }
106: 
107:     if ((response !is Bundle || response.type.value != Bundle.BundleType.Searchset)) {
108:       return emptyList()
109:     }
110: 
111:     response.link
112:       .firstOrNull { component -> component.relation.value == "next" }
113:       ?.url
114:       ?.let { next -> next.value?.let { urlOfTheNextPagesToDownloadForAResource.add(it) } }
115: 
116:     return response.entry
117:       .mapNotNull { it.resource }
118:       .also { resources ->
119:         resources
120:           .groupBy { ResourceType.valueOf(it.resourceType) }
121:           .entries
122:           .forEach { map ->
123:             map.value
124:               .mapNotNull { it.lastUpdated }
125:               .let { lastUpdatedList ->
126:                 if (lastUpdatedList.isNotEmpty()) {
127:                   context.saveLastUpdatedTimestamp(
128:                     map.key,
129:                     lastUpdatedList.maxOrNull()?.toTimeZoneString(),
130:                   )
131:                 }
132:               }
133:           }
134:       } as Collection<Resource>
135:   }
136: 
137:   interface TimestampContext {
138:     suspend fun saveLastUpdatedTimestamp(resourceType: ResourceType, timestamp: String?)
139: 
140:     suspend fun getLasUpdateTimestamp(resourceType: ResourceType): String?
141:   }
142: }

