private enum class AppScreen {
  REGISTER,
  PATIENT_DETAIL,
  NEW_VISIT,
}

private val AncColorScheme =
  lightColorScheme(
    primary = Color(0xFF00695C),
    onPrimary = Color.White,
    primaryContainer = Color(0xFFB2DFDB),
    onPrimaryContainer = Color(0xFF00251A),
    secondary = Color(0xFFAD1457),
    onSecondary = Color.White,
    secondaryContainer = Color(0xFFF8BBD0),
    onSecondaryContainer = Color(0xFF560027),
    background = Color(0xFFF6F9F8),
    surface = Color.White,
    onSurface = Color(0xFF1C1B1F),
    surfaceVariant = Color(0xFFEBF2F0),
    onSurfaceVariant = Color(0xFF424947),
  )

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent {
      MaterialTheme(colorScheme = AncColorScheme) {
        Surface(
          modifier = Modifier.fillMaxSize(),
          color = MaterialTheme.colorScheme.background,
        ) {
          AncClinicApp()
        }
      }
    }
  }
}

@Composable
fun AncClinicApp(viewModel: AncViewModel = viewModel()) {
  val uiState by viewModel.uiState.collectAsState()
  var currentScreen by rememberSaveable { mutableStateOf(AppScreen.REGISTER) }
  var selectedPatientId by rememberSaveable { mutableStateOf<String?>(null) }
  var formInstanceCounter by rememberSaveable { mutableIntStateOf(0) }

  val snackbarHostState = remember { SnackbarHostState() }

  LaunchedEffect(uiState.errorMessage) {
    uiState.errorMessage?.let { msg ->
      snackbarHostState.showSnackbar(msg)
      viewModel.clearError()
    }
  }

  when (currentScreen) {
    AppScreen.REGISTER -> {
      RegisterScreen(
        patients = uiState.patients,
        isLoading = uiState.isLoading,
        isSyncing = uiState.isSyncing,
        snackbarHostState = snackbarHostState,
        onRefresh = { viewModel.refreshAndSync() },
        onPatientClick = { patient ->
          selectedPatientId = patient.id
          viewModel.selectPatient(patient.id)
          currentScreen = AppScreen.PATIENT_DETAIL
        },
      )
    }

    AppScreen.PATIENT_DETAIL -> {
      BackHandler { currentScreen = AppScreen.REGISTER }
      val patient =
        uiState.selectedPatient ?: uiState.patients.find { it.id == selectedPatientId }
      PatientDetailScreen(
        patient = patient,
        visits = uiState.selectedPatientVisits,
        snackbarHostState = snackbarHostState,
        onBack = { currentScreen = AppScreen.REGISTER },
        onRecordNewVisit = {
          formInstanceCounter++
          currentScreen = AppScreen.NEW_VISIT
        },
      )
    }

    AppScreen.NEW_VISIT -> {
      BackHandler { currentScreen = AppScreen.PATIENT_DETAIL }
      val patientId = selectedPatientId ?: uiState.selectedPatient?.id.orEmpty()
      val patientName = uiState.selectedPatient?.name ?: "Patient"
      NewAncVisitScreen(
        patientName = patientName,
        questionnaireJson = uiState.questionnaireJson,
        formInstanceKey = formInstanceCounter,
        isSaving = uiState.isSavingVisit,
        snackbarHostState = snackbarHostState,
        onCancel = { currentScreen = AppScreen.PATIENT_DETAIL },
        onSubmit = { responseProvider ->
          viewModel.saveQuestionnaireVisit(
            patientId = patientId,
            responseProvider = responseProvider,
            onSaved = { currentScreen = AppScreen.PATIENT_DETAIL },
          )
        },
      )
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
  patients: List<PatientSummary>,
  isLoading: Boolean,
  isSyncing: Boolean,
  snackbarHostState: SnackbarHostState,
  onRefresh: () -> Unit,
  onPatientClick: (PatientSummary) -> Unit,
) {
  Scaffold(
    snackbarHost = { SnackbarHost(snackbarHostState) },
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text(
              text = "ANC Register",
              style = MaterialTheme.typography.titleLarge,
              fontWeight = FontWeight.Bold,
            )
            Text(
              text = "Pregnant patients sorted by due date (soonest first)",
              style = MaterialTheme.typography.bodySmall,
              color = MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.85f),
            )
          }
        },
        actions = {
          IconButton(onClick = onRefresh, enabled = !isSyncing) {
            if (isSyncing) {
              CircularProgressIndicator(
                modifier = Modifier.size(20.dp),
                color = MaterialTheme.colorScheme.onPrimary,
                strokeWidth = 2.dp,
              )
            } else {
              Icon(
                imageVector = Icons.Default.Refresh,
                contentDescription = "Sync with server",
                tint = MaterialTheme.colorScheme.onPrimary,
              )
            }
          }
        },
        colors =
          TopAppBarDefaults.topAppBarColors(
            containerColor = MaterialTheme.colorScheme.primary,
            titleContentColor = MaterialTheme.colorScheme.onPrimary,
          ),
      )
    },
  ) { innerPadding ->
    Box(
      modifier = Modifier.fillMaxSize().padding(innerPadding),
    ) {
      when {
        isLoading && patients.isEmpty() -> {
          Column(
            modifier = Modifier.align(Alignment.Center),
            horizontalAlignment = Alignment.CenterHorizontally,
          ) {
            CircularProgressIndicator()
            Spacer(modifier = Modifier.height(12.dp))
            Text(
              text = "Loading ANC Register from FHIR server...",
              style = MaterialTheme.typography.bodyMedium,
              color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
          }
        }

        patients.isEmpty() -> {
          Column(
            modifier = Modifier.align(Alignment.Center).padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
          ) {
            Text(
              text = "No pregnant patients found",
              style = MaterialTheme.typography.titleMedium,
            )
            Spacer(modifier = Modifier.height(8.dp))
            Button(onClick = onRefresh) { Text("Retry Sync") }
          }
        }

        else -> {
          LazyColumn(
            modifier = Modifier.fillMaxSize(),
            contentPadding = PaddingValues(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
          ) {
            items(patients, key = { it.id }) { patient ->
              PatientRegisterCard(
                patient = patient,
                onClick = { onPatientClick(patient) },
              )
            }
          }
        }
      }
    }
  }
}

