            color = MaterialTheme.colorScheme.surfaceVariant,
          ) {
            Text(
              text = "GA: ${visit.gestationalAgeWeeks} wks",
              modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp),
              style = MaterialTheme.typography.labelMedium,
              fontWeight = FontWeight.SemiBold,
            )
          }
        }
      }

      Spacer(modifier = Modifier.height(12.dp))

      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(12.dp),
      ) {
        VitalMetricBox(
          modifier = Modifier.weight(1f),
          icon = Icons.Default.MonitorWeight,
          label = "Weight",
          value = visit.weightKg?.let { "$it kg" } ?: "—",
        )
        VitalMetricBox(
          modifier = Modifier.weight(1f),
          icon = Icons.Default.Favorite,
          label = "Blood Pressure",
          value = visit.bpDisplay?.let { "$it mmHg" } ?: "—",
        )
        if (visit.hemoglobinGdl != null) {
          VitalMetricBox(
            modifier = Modifier.weight(1f),
            icon = Icons.Default.Science,
            label = "Hemoglobin",
            value = "${visit.hemoglobinGdl} g/dL",
          )
        }
      }

      if (visit.dangerSigns.isNotEmpty()) {
        Spacer(modifier = Modifier.height(10.dp))
        FlowRow(
          horizontalArrangement = Arrangement.spacedBy(6.dp),
          verticalArrangement = Arrangement.spacedBy(4.dp),
        ) {
          visit.dangerSigns.forEach { sign ->
            val isNone = sign.equals("none", ignoreCase = true)
            AssistChip(
              onClick = {},
              label = { Text(sign) },
              leadingIcon =
                if (!isNone) {
                  {
                    Icon(
                      imageVector = Icons.Default.Warning,
                      contentDescription = null,
                      modifier = Modifier.size(16.dp),
                      tint = MaterialTheme.colorScheme.error,
                    )
                  }
                } else {
                  null
                },
              colors =
                AssistChipDefaults.assistChipColors(
                  containerColor =
                    if (isNone) {
                      MaterialTheme.colorScheme.surfaceVariant
                    } else {
                      MaterialTheme.colorScheme.errorContainer
                    },
                  labelColor =
                    if (isNone) {
                      MaterialTheme.colorScheme.onSurfaceVariant
                    } else {
                      MaterialTheme.colorScheme.onErrorContainer
                    },
                ),
            )
          }
        }
      }

      if (!visit.notes.isNullOrBlank()) {
        Spacer(modifier = Modifier.height(8.dp))
        Text(
          text = "Notes: ${visit.notes}",
          style = MaterialTheme.typography.bodyMedium,
          color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
      }
    }
  }
}

@Composable
fun VitalMetricBox(
  modifier: Modifier = Modifier,
  icon: ImageVector,
  label: String,
  value: String,
) {
  Surface(
    modifier = modifier,
    shape = RoundedCornerShape(10.dp),
    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.65f),
  ) {
    Column(modifier = Modifier.padding(10.dp)) {
      Row(verticalAlignment = Alignment.CenterVertically) {
        Icon(
          imageVector = icon,
          contentDescription = null,
          modifier = Modifier.size(14.dp),
          tint = MaterialTheme.colorScheme.primary,
        )
        Spacer(modifier = Modifier.width(4.dp))
        Text(
          text = label,
          style = MaterialTheme.typography.labelSmall,
          color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
      }
      Spacer(modifier = Modifier.height(4.dp))
      Text(
        text = value,
        style = MaterialTheme.typography.bodyMedium,
        fontWeight = FontWeight.Bold,
      )
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NewAncVisitScreen(
  patientName: String,
  questionnaireJson: String?,
  formInstanceKey: Int,
  isSaving: Boolean,
  snackbarHostState: SnackbarHostState,
  onCancel: () -> Unit,
  onSubmit: ((suspend () -> dev.ohs.fhir.model.r4.QuestionnaireResponse) -> Unit),
) {
  Scaffold(
    snackbarHost = { SnackbarHost(snackbarHostState) },
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text(
              text = "Record ANC Visit",
              style = MaterialTheme.typography.titleLarge,
              fontWeight = FontWeight.Bold,
            )
            Text(
              text = patientName,
              style = MaterialTheme.typography.bodySmall,
              color = MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.9f),
            )
          }
        },
        navigationIcon = {
          IconButton(onClick = onCancel, enabled = !isSaving) {
            Icon(
              imageVector = Icons.AutoMirrored.Filled.ArrowBack,
              contentDescription = "Cancel",
              tint = MaterialTheme.colorScheme.onPrimary,
            )
          }
        },
        colors =
          TopAppBarDefaults.topAppBarColors(
            containerColor = MaterialTheme.colorScheme.primary,
            titleContentColor = MaterialTheme.colorScheme.onPrimary,
          ),
      )
    },
  ) { innerPadding ->
    Box(modifier = Modifier.fillMaxSize().padding(innerPadding)) {
      if (questionnaireJson.isNullOrBlank()) {
        CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
      } else {
        // Append whitespace padding based on formInstanceKey so Questionnaire composable's
        // remember/viewModel key creates a fresh ViewModel for each new visit entry
        val keyedQuestionnaireJson =
          remember(questionnaireJson, formInstanceKey) {
            questionnaireJson + " ".repeat(formInstanceKey)
          }
        Questionnaire(
          questionnaireJson = keyedQuestionnaireJson,
          config =
            QuestionnaireConfig(
              showSubmitButton = true,
              showCancelButton = true,
              showRequiredText = true,
              submitButtonText = "Save Visit",
              showSubmitAnywayWhenValidationFails = false,
            ),
          onSubmit = onSubmit,
          onCancel = onCancel,
        )
      }

      if (isSaving) {
        Box(
          modifier =
            Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.3f)),
          contentAlignment = Alignment.Center,
        ) {
          CircularProgressIndicator()
        }
      }
    }
  }
}

